const listGrants = `-- name: ListGrants :many
SELECT grant_id, revision, tenant_id, subject_type, subject_id, server_id, descriptor_revision, descriptor_digest, methods, purpose, cost_cap_currency, cost_cap_amount, state, control_receipt_id, expires_at, command_id, request_digest, created_at, updated_at, canonical_resource, transport, protocol_version, issuer, audience, resource_selectors, prompt_selectors, data_class, policy_digest, policy_epoch, failure_code, registration_command_id, revocation_command_id, fenced_at, in_flight_calls, unknown_calls, control_state, revoked_at FROM grants
WHERE tenant_id = $1 AND ($2::text = '' OR state = $2::text)
  AND ($3::boolean OR subject_type = 'tenant'
       OR (subject_type = 'project' AND subject_id = $4::text)
       OR (subject_type = 'actor' AND subject_id = $5::text))
  AND grant_id > $6::text
ORDER BY grant_id LIMIT $7
`

type ListGrantsParams struct {
	TenantID   string
	State      string
	ReadAll    bool
	ProjectID  string
	ActorID    string
	AfterGrant string
	PageLimit  int32
}

func (q *Queries) ListGrants(ctx context.Context, arg ListGrantsParams) ([]Grant, error) {
	rows, err := q.db.Query(ctx, listGrants,
		arg.TenantID,
		arg.State,
		arg.ReadAll,
		arg.ProjectID,
		arg.ActorID,
		arg.AfterGrant,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Grant{}
	for rows.Next() {
		var i Grant
		if err := rows.Scan(
			&i.GrantID,
			&i.Revision,
			&i.TenantID,
			&i.SubjectType,
			&i.SubjectID,
			&i.ServerID,
			&i.DescriptorRevision,
			&i.DescriptorDigest,
			&i.Methods,
			&i.Purpose,
			&i.CostCapCurrency,
			&i.CostCapAmount,
			&i.State,
			&i.ControlReceiptID,
			&i.ExpiresAt,
			&i.CommandID,
			&i.RequestDigest,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CanonicalResource,
			&i.Transport,
			&i.ProtocolVersion,
			&i.Issuer,
			&i.Audience,
			&i.ResourceSelectors,
			&i.PromptSelectors,
			&i.DataClass,
			&i.PolicyDigest,
			&i.PolicyEpoch,
			&i.FailureCode,
			&i.RegistrationCommandID,
			&i.RevocationCommandID,
			&i.FencedAt,
			&i.InFlightCalls,
			&i.UnknownCalls,
			&i.ControlState,
			&i.RevokedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

