const updateGrantBarrier = `-- name: UpdateGrantBarrier :execrows
UPDATE grants SET state = $2, control_receipt_id = $3, policy_epoch = $4, failure_code = $5, revocation_command_id = $6, fenced_at = $7,
    in_flight_calls = $8, unknown_calls = $9, control_state = $10, revoked_at = $11, updated_at = now()
WHERE grant_id = $1 AND state = $12
`

type UpdateGrantBarrierParams struct {
	GrantID             string
	State               string
	ControlReceiptID    *string
	PolicyEpoch         *int64
	FailureCode         *string
	RevocationCommandID *string
	FencedAt            pgtype.Timestamptz
	InFlightCalls       int64
	UnknownCalls        int64
	ControlState        string
	RevokedAt           pgtype.Timestamptz
	ExpectedState       string
}

func (q *Queries) UpdateGrantBarrier(ctx context.Context, arg UpdateGrantBarrierParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateGrantBarrier,
		arg.GrantID,
		arg.State,
		arg.ControlReceiptID,
		arg.PolicyEpoch,
		arg.FailureCode,
		arg.RevocationCommandID,
		arg.FencedAt,
		arg.InFlightCalls,
		arg.UnknownCalls,
		arg.ControlState,
		arg.RevokedAt,
		arg.ExpectedState,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
